// Server-side upload validation constants.
// These are enforced on every upload request regardless of any client-side checks.

export const MAX_FILE_SIZE = 2097152 // 2 MiB, in bytes

export const ALLOWED_MIME_TYPES = [
  'image/png',
  'image/jpeg',
  'image/gif',
  'image/webp',
] as const

export type AllowedMimeType = (typeof ALLOWED_MIME_TYPES)[number]

export function isAllowedMimeType(mime: string): mime is AllowedMimeType {
  return (ALLOWED_MIME_TYPES as readonly string[]).includes(mime)
}

// Durable storage layer: SQLite for metadata, local disk for file bytes.
// This module is only ever imported from server-only route handlers, so it
// is safe to use Node built-ins and native modules here.
import fs from 'node:fs'
import path from 'node:path'
import Database from 'better-sqlite3'

const DATA_DIR = process.env.GALLERY_DATA_DIR || path.join(process.cwd(), 'data')
export const UPLOADS_DIR = path.join(DATA_DIR, 'uploads')
const DB_PATH = path.join(DATA_DIR, 'gallery.sqlite')

fs.mkdirSync(UPLOADS_DIR, { recursive: true })

const db = new Database(DB_PATH)
db.pragma('journal_mode = WAL')

db.exec(`
  CREATE TABLE IF NOT EXISTS files (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    filename TEXT NOT NULL,
    size INTEGER NOT NULL,
    mime TEXT NOT NULL,
    uploaded_at TEXT NOT NULL,
    disk_filename TEXT NOT NULL
  )
`)

export interface FileRecord {
  id: number
  filename: string
  size: number
  mime: string
  uploaded_at: string
  disk_filename: string
}

export interface FileMeta {
  id: number
  filename: string
  size: number
  mime: string
  uploadedAt: string
}

export function toApiShape(record: FileRecord): FileMeta {
  return {
    id: record.id,
    filename: record.filename,
    size: record.size,
    mime: record.mime,
    uploadedAt: record.uploaded_at,
  }
}

export function insertFile(data: {
  filename: string
  size: number
  mime: string
  uploadedAt: string
  diskFilename: string
}): FileRecord {
  const stmt = db.prepare(
    `INSERT INTO files (filename, size, mime, uploaded_at, disk_filename) VALUES (?, ?, ?, ?, ?)`,
  )
  const info = stmt.run(
    data.filename,
    data.size,
    data.mime,
    data.uploadedAt,
    data.diskFilename,
  )
  return getFileById(Number(info.lastInsertRowid))!
}

export function listFiles(): Array<FileRecord> {
  return db
    .prepare(`SELECT * FROM files ORDER BY id DESC`)
    .all() as Array<FileRecord>
}

export function getFileById(id: number): FileRecord | undefined {
  return db.prepare(`SELECT * FROM files WHERE id = ?`).get(id) as
    | FileRecord
    | undefined
}

export function deleteFileById(id: number): boolean {
  const info = db.prepare(`DELETE FROM files WHERE id = ?`).run(id)
  return info.changes > 0
}

import { createFileRoute } from '@tanstack/react-router'
import { randomUUID } from 'node:crypto'
import { writeFile } from 'node:fs/promises'
import path from 'node:path'
import { UPLOADS_DIR, insertFile, toApiShape } from '~/server/db'
import { MAX_FILE_SIZE, isAllowedMimeType } from '~/server/validation'

export const Route = createFileRoute('/api/upload')({
  server: {
    handlers: {
      POST: async ({ request }) => {
        let formData: FormData
        try {
          formData = await request.formData()
        } catch {
          return Response.json(
            { error: 'Request must be multipart/form-data.' },
            { status: 400 },
          )
        }

        const file = formData.get('file')
        if (!(file instanceof File)) {
          return Response.json(
            { error: 'Missing file under form field "file".' },
            { status: 400 },
          )
        }

        const mime = file.type
        if (!isAllowedMimeType(mime)) {
          return Response.json(
            {
              error: `File type "${mime || 'unknown'}" is not allowed. Allowed types: image/png, image/jpeg, image/gif, image/webp.`,
            },
            { status: 400 },
          )
        }

        if (file.size > MAX_FILE_SIZE) {
          return Response.json(
            {
              error: `File size ${file.size} bytes exceeds the maximum allowed size of ${MAX_FILE_SIZE} bytes.`,
            },
            { status: 400 },
          )
        }

        const diskFilename = randomUUID()
        const buffer = Buffer.from(await file.arrayBuffer())
        await writeFile(path.join(UPLOADS_DIR, diskFilename), buffer)

        const record = insertFile({
          filename: file.name || 'upload',
          size: file.size,
          mime,
          uploadedAt: new Date().toISOString(),
          diskFilename,
        })

        return Response.json(toApiShape(record), { status: 201 })
      },
    },
  },
})

import { createFileRoute } from '@tanstack/react-router'
import { listFiles, toApiShape } from '~/server/db'

export const Route = createFileRoute('/api/files')({
  server: {
    handlers: {
      GET: async () => {
        const files = listFiles().map(toApiShape)
        return Response.json(files, { status: 200 })
      },
    },
  },
})

import { createFileRoute } from '@tanstack/react-router'
import { readFile, unlink } from 'node:fs/promises'
import path from 'node:path'
import { UPLOADS_DIR, deleteFileById, getFileById } from '~/server/db'

function parseId(raw: string): number | undefined {
  const id = Number(raw)
  return Number.isInteger(id) ? id : undefined
}

export const Route = createFileRoute('/api/files/$id')({
  server: {
    handlers: {
      GET: async ({ params }) => {
        const id = parseId(params.id)
        const record = id === undefined ? undefined : getFileById(id)
        if (!record) {
          return Response.json({ error: 'File not found.' }, { status: 404 })
        }

        try {
          const data = await readFile(
            path.join(UPLOADS_DIR, record.disk_filename),
          )
          return new Response(data, {
            status: 200,
            headers: {
              'Content-Type': record.mime,
              'Content-Length': String(record.size),
            },
          })
        } catch {
          return Response.json({ error: 'File not found.' }, { status: 404 })
        }
      },
      DELETE: async ({ params }) => {
        const id = parseId(params.id)
        const record = id === undefined ? undefined : getFileById(id)
        if (!record) {
          return Response.json({ error: 'File not found.' }, { status: 404 })
        }

        deleteFileById(record.id)
        try {
          await unlink(path.join(UPLOADS_DIR, record.disk_filename))
        } catch {
          // File bytes already missing on disk; metadata removal still succeeds.
        }

        return Response.json({ ok: true }, { status: 200 })
      },
    },
  },
})

import { createFileRoute } from '@tanstack/react-router'
import * as React from 'react'

interface FileMeta {
  id: number
  filename: string
  size: number
  mime: string
  uploadedAt: string
}

export const Route = createFileRoute('/')({
  component: Home,
})

function formatSize(bytes: number): string {
  if (bytes < 1024) return `${bytes} B`
  if (bytes < 1024 * 1024) return `${(bytes / 1024).toFixed(1)} KB`
  return `${(bytes / (1024 * 1024)).toFixed(1)} MB`
}

function Home() {
  const [files, setFiles] = React.useState<Array<FileMeta>>([])
  const [loading, setLoading] = React.useState(true)
  const [error, setError] = React.useState('')
  const [uploading, setUploading] = React.useState(false)
  const fileInputRef = React.useRef<HTMLInputElement>(null)

  const loadFiles = React.useCallback(async () => {
    try {
      const res = await fetch('/api/files')
      if (res.ok) {
        const data = (await res.json()) as Array<FileMeta>
        setFiles(data)
      }
    } finally {
      setLoading(false)
    }
  }, [])

  React.useEffect(() => {
    loadFiles()
  }, [loadFiles])

  async function handleUpload() {
    setError('')
    const input = fileInputRef.current
    const file = input?.files?.[0]
    if (!file) {
      setError('Please choose a file to upload first.')
      return
    }

    setUploading(true)
    try {
      const formData = new FormData()
      formData.append('file', file)
      const res = await fetch('/api/upload', {
        method: 'POST',
        body: formData,
      })
      const data = await res.json().catch(() => ({}))
      if (!res.ok) {
        setError(
          typeof data?.error === 'string' ? data.error : 'Upload failed.',
        )
        return
      }
      setFiles((prev) => [data as FileMeta, ...prev])
      if (input) input.value = ''
    } catch {
      setError('Upload failed. Please try again.')
    } finally {
      setUploading(false)
    }
  }

  async function handleDelete(id: number) {
    const res = await fetch(`/api/files/${id}`, { method: 'DELETE' })
    if (res.ok) {
      setFiles((prev) => prev.filter((f) => f.id !== id))
    }
  }

  return (
    <div className="p-6 max-w-3xl mx-auto">
      <h1 className="text-2xl font-bold mb-4">Image Upload Gallery</h1>

      <div className="flex items-center gap-3 mb-2 flex-wrap">
        <input
          ref={fileInputRef}
          type="file"
          data-testid="file-input"
          accept="image/png,image/jpeg,image/gif,image/webp"
        />
        <button
          type="button"
          data-testid="upload-button"
          onClick={handleUpload}
          disabled={uploading}
          className="px-4 py-2 bg-blue-600 text-white rounded-sm disabled:opacity-50"
        >
          {uploading ? 'Uploading…' : 'Upload'}
        </button>
      </div>

      {error ? (
        <div data-testid="upload-error" role="alert" className="text-red-600 mb-4">
          {error}
        </div>
      ) : null}

      <hr className="my-4" />

      {loading ? (
        <p>Loading…</p>
      ) : files.length === 0 ? (
        <p>No files uploaded yet.</p>
      ) : (
        <ul className="grid grid-cols-2 sm:grid-cols-3 gap-4">
          {files.map((f) => (
            <li
              key={f.id}
              data-testid="gallery-item"
              data-file-id={f.id}
              className="border rounded-sm p-2"
            >
              <a
                href={`/api/files/${f.id}`}
                data-testid="file-link"
                target="_blank"
                rel="noreferrer"
              >
                {f.mime.startsWith('image/') ? (
                  <img
                    src={`/api/files/${f.id}`}
                    alt={f.filename}
                    className="w-full h-32 object-cover mb-2 rounded-sm"
                  />
                ) : null}
              </a>
              <div data-testid="file-name" className="text-sm truncate">
                {f.filename}
              </div>
              <div className="text-xs text-gray-500">
                {formatSize(f.size)} · {f.mime}
              </div>
              <button
                type="button"
                data-testid="delete-button"
                onClick={() => handleDelete(f.id)}
                className="mt-2 text-sm text-red-600 underline"
              >
                Delete
              </button>
            </li>
          ))}
        </ul>
      )}
    </div>
  )
}

